def test_generate_ids_generates_monotonically_increasing_ids(client):
    ids = []
    for index in range(100000):
        if index % 10000 == 0:
            time.sleep(0.001)
        ids.append(tb.id())
    assert all(ids[i - 1] < ids[i] for i in range(1, len(ids)))

