    assert transfers[0].code == 7
    assert transfers[0].user_data_128 == user_data_128
    assert transfers[0].user_data_64 == 8888888888
    assert transfers[0].user_data_32 == 54321
    transfer = transfers[0]
    assert transfer.timestamp > 0

