def test_query_accounts_returns_accounts_matching_user_data(client):
    account_1_id = tb.id()
    account_2_id = tb.id()
    user_data = tb.id()
    client.create_accounts(
        [
            tb.Account(
                id=account_1_id,
                user_data_128=user_data,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=account_2_id,
                user_data_128=user_data,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=tb.id(),
                user_data_128=tb.id(),
                ledger=1,
                code=1,
            ),
        ]
    )
    accounts = client.query_accounts(
        tb.QueryFilter(
            user_data_128=user_data,
            user_data_64=0,
            user_data_32=0,
            ledger=0,
            code=0,
            timestamp_min=0,
            timestamp_max=0,
            limit=10,
            flags=tb.QueryFilterFlags.NONE,
        )
    )
    assert len(accounts) == 2
    assert accounts[0].id == account_1_id
    assert accounts[0].user_data_128 == user_data
    assert accounts[1].id == account_2_id
    assert accounts[1].user_data_128 == user_data

