def test_query_accounts_pages_through_reversed_accounts_with_a_timestamp_cursor(client):
    account_1_id = tb.id()
    account_2_id = tb.id()
    account_3_id = tb.id()
    user_data = tb.id()
    client.create_accounts(
        [
            tb.Account(
                id=account_1_id,
                user_data_128=user_data,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=account_2_id,
                user_data_128=user_data,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=account_3_id,
                user_data_128=user_data,
                ledger=1,
                code=1,
            ),
        ]
    )
    page_1 = client.query_accounts(
        tb.QueryFilter(
            user_data_128=user_data,
            user_data_64=0,
            user_data_32=0,
            ledger=0,
            code=0,
            timestamp_min=0,
            timestamp_max=0,
            limit=2,
            flags=tb.QueryFilterFlags.REVERSED,
        )
    )
    assert len(page_1) == 2
    assert page_1[0].id == account_3_id
    assert page_1[1].id == account_2_id
    page_1_last = page_1[1]
    cursor_1 = page_1_last.timestamp
    page_2 = client.query_accounts(
        tb.QueryFilter(
            user_data_128=user_data,
            user_data_64=0,
            user_data_32=0,
            ledger=0,
            code=0,
            timestamp_min=0,
            timestamp_max=cursor_1 - 1,
            limit=2,
            flags=tb.QueryFilterFlags.REVERSED,
        )
    )
    assert len(page_2) == 1
    assert page_2[0].id == account_1_id
    page_2_last = page_2[0]
    cursor_2 = page_2_last.timestamp
    page_3 = client.query_accounts(
        tb.QueryFilter(
            user_data_128=user_data,
            user_data_64=0,
            user_data_32=0,
            ledger=0,
            code=0,
            timestamp_min=0,
            timestamp_max=cursor_2 - 1,
            limit=2,
            flags=tb.QueryFilterFlags.REVERSED,
        )
    )
    assert page_3 == []

