# Suite: create_transfers_concurrent

def test_create_transfers_concurrent_applies_transfers_submitted_concurrently(client):
    debit_account_id = tb.id()
    credit_account_id = tb.id()
    client.create_accounts(
        [
            tb.Account(
                id=debit_account_id,
                ledger=1,
                code=1,
            ),
            tb.Account(
                id=credit_account_id,
                ledger=1,
                code=1,
            ),
        ]
    )
    def operation():
        client.create_transfers(
            [
                tb.Transfer(
                    id=tb.id(),
                    debit_account_id=debit_account_id,
                    credit_account_id=credit_account_id,
                    amount=10,
                    ledger=1,
                    code=1,
                ),
            ]
        )

    threads = [threading.Thread(target=operation) for _ in range(100)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    accounts = client.lookup_accounts([debit_account_id, credit_account_id])
    assert len(accounts) == 2
    assert accounts[0].id == debit_account_id
    assert accounts[0].debits_posted == 1000
    assert accounts[0].credits_posted == 0
    assert accounts[1].id == credit_account_id
    assert accounts[1].debits_posted == 0
    assert accounts[1].credits_posted == 1000

